  insert into public.brands (name, website, description, country, status) values ('PURE MAMA', 'https://us.puremama.com', 'Premium naturally derived skincare brand for pregnancy, birth and postpartum (welcome to any skincare creator) running a Creator Community on ShopMy: 20% commission on every sale through a unique ShopMy link, a welcome gift for approved creators, bonuses for high performers, and a 5,000+ follower guideline with a minimum of one Story, Reel or TikTok to stay active.', 'United States', 'published') returning id into bid;
