  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShopMy', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://us.puremama.com/pages/us-brand-ambassador-enquiry-form.', 'https://us.puremama.com/pages/us-brand-ambassador-enquiry-form', 'needs_review', now());
