  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.puremama.com/pages/us-brand-ambassador-enquiry-form', 'official_site', 'affiliate', 'PURE MAMA''s own Creator Community page states ''Enjoy 20% commission on every sale driven through your affiliate links'' and its FAQ repeats ''PURE MAMA creators earn 20% commission on every sale driven through their unique ShopMy link'', paid via ShopMy on its standard schedule, with bonuses for high-performing affiliates. No cap statement appears anywhere on the fetched page, so the earnings cap is recorded as unknown, never guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.puremama.com/pages/us-brand-ambassador-enquiry-form', 'official_site', 'ugc_collab', 'The page is a structured creator program: approved creators receive a welcome gift and brand resources, early access to launches, and must share at least one Story, Reel or TikTok featuring the brand to remain active; the guideline is 5,000+ followers and anyone who loves premium naturally derived skincare may apply, pregnant or not.', 'verified', now());
