  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 18, 10, 8, 4, '{"niche_fit": "Pregnancy-to-postpartum skincare routines, storytelling and product education are proven short-form skincare formats, and the brand explicitly welcomes non-pregnant skincare creators too.", "ugc_evidence": "A named Creator Community with a posting requirement, welcome gift, creator resources and early access \u2014 structured UGC evidence on the brand''s own page.", "compensation": "A clean published 20% on every sale plus high-performer bonuses; no cap statement was published, so the cap is honestly unknown.", "contact_access": "Application form with social handles on the brand''s own US site; no partnerships email is published.", "opportunity_availability": "Open application, free to join; existing ShopMy members can start linking immediately, though the guideline asks for 5,000+ followers.", "credibility": "Premium positioned DTC brand with a clear program page and ShopMy payment infrastructure; no retail distribution verified in this research."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Charlotte Tilbury', 'https://www.charlottetilbury.com', 'Global luxury makeup and skincare brand founded by makeup artist Charlotte Tilbury; its own Affiliate Programme page recruits sites, blogs and influencers to earn commission on all sales at CharlotteTilbury.com, tracked and paid through Partnerize, with applications reviewed within 7 days and partnerships@charlottetilbury.com published for questions.', 'United Kingdom', 'published') returning id into bid;
