  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Partnerize', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.charlottetilbury.com/us/content/charlotte-tilbury-affiliate-program.', 'https://www.charlottetilbury.com/us/content/charlotte-tilbury-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Charlotte Tilbury Affiliate Programme (Partnerize)', 'https://www.charlottetilbury.com/us/content/charlotte-tilbury-affiliate-program', 'https://www.charlottetilbury.com/us/content/charlotte-tilbury-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.charlottetilbury.com/us/content/charlotte-tilbury-affiliate-program', 'official_site', 'affiliate', 'Charlotte Tilbury''s own affiliate page states affiliates ''earn commission on all sales each time your visitors complete a purchase at CharlotteTilbury.com'', that it has ''teamed up with Partnerize for tracking technology, reporting and payment processing'', that applications are reviewed within 7 days, and publishes partnerships@charlottetilbury.com. The official page publishes no percentage and no cap statement, so both the rate and the cap need the network listing to settle.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/category/beauty-skincare', 'affiliate_network', 'affiliate', 'Third-party rate sources for Charlotte Tilbury conflict and cannot be settled: LinkApprove lists up to 8% on a 30-day cookie, Lasso lists 6.4%, other roundups claim 8-10% and one claims up to 25%. Because the brand''s own page publishes no rate, commission_rate is recorded as null with the conflict documented here. No source states an earnings cap, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.charlottetilbury.com/us/content/charlotte-tilbury-affiliate-program', 'official_site', 'creator_saturation', 'No hard absolute creator count for Charlotte Tilbury''s affiliate program surfaced; it is a large global program, but with no ~100-scale count published, saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 16, 11, 13, 9, 5, '{"niche_fit": "Pillow Talk and Magic Cream are among the most-tutorialled luxury beauty products on TikTok and Instagram \u2014 top-tier makeup UGC fit.", "ugc_evidence": "An official affiliate programme that explicitly names Influencer as a joinable vertical on Partnerize, plus a separate Pro programme for makeup artists.", "compensation": "Commission on all sales is confirmed on the brand''s own page, but published rates conflict across sources (6.4% to up to 25%), so no rate is recorded and compensation scores mid-range; cap unknown.", "contact_access": "Published partnerships email plus the full programme page on the brand''s own site \u2014 direct contact access.", "opportunity_availability": "Open Partnerize application with a stated 7-day review; global campaigns available to existing Partnerize accounts.", "credibility": "One of the world''s best-known luxury beauty brands, owned by Puig, sold globally through its own site and major retailers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Morphe', 'https://www.morphe.com', 'Creator-born makeup brand (palettes, brushes, lip) whose Morphe Artistry Collective is its own ambassador gateway: members complete creative tasks, unlock product vouchers, earn affiliate commission and can be featured on Morphe''s socials; open to US creators 18+ with at least 1,000 followers on Instagram or TikTok.', 'United States', 'published') returning id into bid;
