  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Morphe Artistry Collective (ambassador / affiliate)', 'https://www.morphe.com/pages/morphe-artistry-collective', 'https://www.morphe.com/pages/morphe-artistry-collective', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.morphe.com/pages/morphe-artistry-collective', 'official_site', 'affiliate', 'Morphe''s own Artistry Collective page lists ''Earn affiliate commission'' among its benefits alongside product vouchers and a chance to feature on Morphe''s socials, with eligibility of a public profile, at least 1,000 followers on Instagram or TikTok, 18+ and US-based. The brand''s own help page confirms this Collective is the route to collaborate or join the affiliate program. The official pages publish no percentage and no cap statement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/morphe-com-affiliate-program', 'affiliate_network', 'affiliate', 'Third-party rate sources conflict and cannot be settled: Shopper lists 5-10%, Lasso lists up to 5.25% (and 6% for Morphe Brushes), and a ShareASale listing shows 12%. Because Morphe''s own pages publish no rate, commission_rate is recorded as null with the conflict documented. No source states an earnings cap, so the cap is unknown.', 'publicly_reported', now());
