  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 11, 10, 9, 4, '{"niche_fit": "Affordable palettes, brushes and viral makeup looks are core beauty-UGC material, and Morphe was built on creator content.", "ugc_evidence": "A named creator collective built around creative tasks, levels and social features, with affiliate commission as a stated benefit \u2014 strong structured UGC evidence.", "compensation": "Affiliate commission is confirmed on the brand''s own page, but rates conflict across third-party sources (5.25% to 12%), so no rate is recorded; cap unknown.", "contact_access": "Application runs from the brand''s own Collective page into its community platform; no partnerships email is published there.", "opportunity_availability": "Open application with a low 1,000-follower bar, but US-only and 18+.", "credibility": "Long-established, widely distributed makeup brand; the Collective is a current, live program on its own site."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('The Honest Company', 'https://www.honest.com', 'Jessica Alba-founded clean beauty, baby and home brand whose ''Become an Honest Brand Ambassador'' page recruits beauty enthusiasts and parents to post about favourite products and monetise through ShopMy affiliate links; ShopMy accounts typically need 1,000 followers on one account, reviewed case by case, with 3-5 business day reviews.', 'United States', 'published') returning id into bid;
