  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Honest Brand Ambassador Program (ShopMy)', 'https://honest.com/pages/become-an-honest-brand-ambassador', 'https://honest.com/pages/become-an-honest-brand-ambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://honest.com/pages/become-an-honest-brand-ambassador', 'official_site', 'affiliate', 'Honest''s own ambassador page recruits ''the modern mama, beauty enthusiast and all-around Honest brand loyalist to post about their fave products'' with an Apply Now route into ShopMy, and explains that ShopMy converts products into affiliate links and pays weekly via PayPal or Stripe. The 10-30% range quoted on that page is ShopMy''s platform-wide typical range across retailers, not an Honest-specific rate, and a third-party listing claims 5-10% for Honest — the rates cannot be settled, so commission_rate is null. No cap statement is published, so the cap is unknown.', 'verified', now());
