  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 10, 11, 8, 5, '{"niche_fit": "Clean beauty and baby-care staples with a loyal parent audience fit routine, haul and ''clean swaps'' UGC.", "ugc_evidence": "A dedicated ambassador page on the brand''s own site recruiting posters and routing them into ShopMy monetisation.", "compensation": "Monetisation via ShopMy is confirmed, but no Honest-specific rate is published (the page''s 10-30% is ShopMy''s generic range and a third party claims 5-10%), so the rate is null; cap unknown.", "contact_access": "Published influencer email (influencers@honest.com, per a listing checked against the brand''s own pages) plus the ambassador application on honest.com.", "opportunity_availability": "Open application through ShopMy with a typical 1,000-follower guideline, case-by-case review and 3-5 business day turnaround.", "credibility": "Publicly traded, nationally distributed clean-products company founded by Jessica Alba."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bachca', 'https://us.bachca.com', 'French-designed hair brushes, accessories and beauty tools brand (Bachca Paris) running a Creator Program for US and Canada audiences through Shopify Collabs, with ShopMy as a second route: commission on every sale on new and returning customers, gifted products for selected creators, paid content usage agreed in advance, and no minimum following — micro-creators welcome.', 'France', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://us.bachca.com/pages/collab', 'https://us.bachca.com/pages/collab', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://us.bachca.com/pages/collab.', 'https://us.bachca.com/pages/collab', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bachca Creator Program (Shopify Collabs / ShopMy)', 'https://us.bachca.com/pages/collab', 'https://us.bachca.com/pages/collab', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.bachca.com/pages/collab', 'official_site', 'affiliate', 'Bachca''s own Creator Program page states creators ''earn commission on every sale you drive'' on new and returning customers, applications run through Shopify Collabs in a few minutes, and creators already on ShopMy can find Bachca Paris there and earn commission on their links. Its FAQ states plainly ''Our commission structure is shared upon approval'', so no rate is published and commission_rate is null. No cap statement appears on the page, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.bachca.com/pages/collab', 'official_site', 'ugc_collab', 'The page is built for UGC: no minimum following, micro-creators welcome, gifted products for selected creators, content ideas published (morning routines, claw-clip how-tos, before/after brushing), and top-performing content may run in ads or whitelisting, always agreed with the creator first.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.bachca.com/pages/collab', 'official_site', 'creator_saturation', 'No hard absolute creator count for Bachca''s Creator Program surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 10, 10, 9, 4, '{"niche_fit": "Giftable French hair brushes and accessories are natural ''get ready with me'', routine and how-to content for beauty and hair creators.", "ugc_evidence": "A dedicated creator program with published content ideas, gifting and paid-usage pathways \u2014 strong UGC structure for a small brand.", "compensation": "Commission on every sale (new and returning) is confirmed, but the rate is shared only upon approval, so it is recorded as null; cap unknown.", "contact_access": "Application and a ''send us a message'' route on the brand''s own US site; no partnerships email is published.", "opportunity_availability": "Open application with no minimum following \u2014 one of the lowest bars in this round \u2014 but audiences must be in the US or Canada.", "credibility": "Established Paris design brand selling through its own US storefront; smaller than the global names in this round."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pure n'' Bio', 'https://purenbio.com', 'Curated French organic beauty and wellness store built for the GCC market (6 Ecocert/COSMOS-certified French brands, made in France) running its own Partner Program: up to 20% commission per order for top-tier partners, 14-30 day tracking, monthly PayPal or bank payouts with no minimum, free to join with no minimum audience, plus yearly bonuses, partner gifts and trips for top performers.', 'United Arab Emirates', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://purenbio.com/pages/join-our-community', 'https://purenbio.com/pages/join-our-community', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://purenbio.com/pages/join-our-community.', 'https://affiliate.purenbio.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pure n'' Bio Partner Program', 'https://affiliate.purenbio.com', 'https://purenbio.com/pages/join-our-community', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purenbio.com/pages/join-our-community', 'official_site', 'affiliate', 'Pure n'' Bio''s own affiliate page publishes ''up to 20% commission per order'' for top-performing partners, a 14-30 day tracking window, free joining with no minimum audience, monthly payouts on the 1st via PayPal or bank transfer with no minimum amount, and applications reviewed within 2 days via its affiliate portal. Only a top-tier ceiling is published — no base rate — so commission_rate is recorded as null (''up to 20%'' is a rate ceiling, not a settled rate). No earnings-cap statement appears on the page, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purenbio.com/pages/join-our-community', 'official_site', 'creator_saturation', 'The brand''s own page states ''1,200+ Active partners — already earning with Pure n'' Bio''. That is an absolute partner count, but at 1,200+ it is far above the ~100 scale that would count as low saturation, so creator saturation is recorded as unknown (not low).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 12, 10, 9, 3, '{"niche_fit": "Certified organic French skincare and makeup, highly visual and strong on Snapchat, TikTok and Instagram per the brand \u2014 a good fit for GCC-focused beauty creators.", "ugc_evidence": "A creator-facing partner program with a seasonal content library, short-form video assets, Arabic and English captions and custom discount codes.", "compensation": "Up to 20% per order for top tiers plus yearly bonuses, but no base rate is published, so the rate is null; cap unknown.", "contact_access": "Application form linked from the brand''s own program page into its affiliate portal; no partnerships email is published.", "opportunity_availability": "Applications open, free, no minimum audience and no exclusivity, reviewed within about 2 days \u2014 but the audience fit is GCC-specific.", "credibility": "Curated multi-brand store rather than a single product brand; certifications (Ecocert, COSMOS) are stated, but it is a young regional retailer."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Caudalie', 'https://www.caudalie.com', 'Family-owned French skincare brand built on grape-derived Vinothérapie actives, running an affiliate program through Awin (also listed via other networks) with a 30-day cookie; published rate sources conflict, so no single rate can be recorded.', 'France', 'published') returning id into bid;
