  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Caudalie Affiliate Program (Awin)', null, 'https://linkapprove.com/affiliate-programs/category/beauty-skincare', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/category/beauty-skincare', 'affiliate_network', 'affiliate', 'LinkApprove''s beauty directory lists the Caudalie affiliate program at up to 8% per sale on a 30-day cookie across US, UK, EU and CA, and multiple sources place the program on Awin. However published rates conflict — one roundup lists 8% for cashback and 12% for bloggers/editorial, while Shopper lists 4% — so commission_rate is recorded as null with the conflict documented. No source states an earnings cap, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/category/beauty-skincare', 'official_site', 'creator_saturation', 'No hard absolute creator count for Caudalie''s affiliate program surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 13, 11, 8, 8, 5, '{"niche_fit": "French pharmacy-style skincare with hero serums is a staple of ingredient-led and routine UGC worldwide.", "ugc_evidence": "A long-running network affiliate program used by beauty bloggers and editorial creators, per multiple directories; no dedicated creator community was published.", "compensation": "Rates conflict across sources (4% vs 8% vs 12% for editorial), so no rate is recorded; cap unknown.", "contact_access": "Access is through the Awin network listing rather than a brand-published contact; no partnerships email was verified on an official page in this research.", "opportunity_availability": "Joinable through Awin across US, UK, EU and CA with a 30-day cookie, subject to network approval.", "credibility": "Established family-owned French skincare house with global retail distribution and its own Vinoth\u00e9rapie spas."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MCoBeauty', 'https://www.mcobeauty.com', 'Australian affordable-luxury makeup and skincare brand (known for premium-inspired products at drugstore prices) running an affiliate program through Commission Factory at a flat 10% commission per sale with a 30-day cookie, open to bloggers, reviewers and content creators across APAC and beyond.', 'Australia', 'published') returning id into bid;
