  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MCoBeauty Affiliate Program (Commission Factory)', null, 'https://getlasso.co/affiliate/mcobeauty/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/mcobeauty/', 'affiliate_network', 'affiliate', 'Lasso''s program listing states the MCoBeauty affiliate program pays 10% per sale with a 30-day cookie across makeup and skincare, and a second independent write-up of the program confirms it runs through Commission Factory at the same flat 10% across the product range, with applications reviewed in a few days. No earnings-cap statement appears in either source, so the cap is recorded as unknown.', 'publicly_reported', now());
