  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 14, 8, 8, 4, '{"niche_fit": "Viral, affordable ''luxe for less'' makeup is heavily reviewed and duped in beauty UGC \u2014 strong content fit.", "ugc_evidence": "A structured network affiliate program aimed at beauty bloggers and creators; no dedicated UGC community page was published.", "compensation": "A flat 10% per sale corroborated by two independent program sources, with a 30-day cookie; cap unknown.", "contact_access": "Access is through Commission Factory rather than a brand-published email; no partnerships contact was verified on an official page in this research.", "opportunity_availability": "Applications through Commission Factory, typically reviewed within a few days.", "credibility": "One of Australia''s fastest-growing beauty brands with major retail distribution in Australia and a growing US presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MIXXGO', 'https://www.mixxgo.com', 'Bold, viral color-makeup brand whose own Affiliate Program page (''Glam with Us. Glow with Us. Grow with Us.'') recruits creators of any size — micro-influencers explicitly welcomed, no website needed — with personal links and promo codes, sales tracked through Rakuten, tiered levels and bonuses, and monthly challenges and giveaways for affiliates.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.mixxgo.com/affiliate-program/', 'https://www.mixxgo.com/affiliate-program/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.mixxgo.com/affiliate-program/.', 'https://www.mixxgo.com/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MIXXGO Affiliate Program (Rakuten)', 'https://www.mixxgo.com/affiliate-program/', 'https://www.mixxgo.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mixxgo.com/affiliate-program/', 'official_site', 'affiliate', 'MIXXGO''s own affiliate page states affiliates track ''every sale and commission through Rakuten'', can promote all products with no product restrictions, and earn ''competitive commission rates with room to grow, plus tiered levels and bonuses'' — but it publishes no percentage anywhere, so commission_rate is null. Its ''Juicy Commissions, No Limits'' heading is explained on the page as being about product restrictions and rules, not as an earnings-cap statement, so the cap is honestly recorded as unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mixxgo.com/affiliate-program/', 'official_site', 'ugc_collab', 'The page is explicitly creator-first: no website or blog needed (Instagram, TikTok, YouTube and Discord named), new creators and micro-influencers welcomed, free to join in a five-minute application, plus monthly challenges, events and giveaways exclusive to affiliates.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mixxgo.com/affiliate-program/', 'official_site', 'creator_saturation', 'No hard absolute creator count for MIXXGO surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 10, 9, 9, 3, '{"niche_fit": "Bold, trend-led color makeup built for TikTok and Instagram looks is a natural short-form beauty format.", "ugc_evidence": "A creator-first program page naming social platforms, welcoming micro-influencers and running affiliate-only challenges and giveaways.", "compensation": "Tiered rates and bonuses are promised through Rakuten, but no percentage is published anywhere on the fetched page, so the rate is null; cap unknown (the ''No Limits'' heading covers product restrictions, not earnings).", "contact_access": "Apply Now route on the brand''s own program page; no partnerships email is published.", "opportunity_availability": "Free, five-minute application with no website or follower requirement stated.", "credibility": "Small, young viral-makeup brand; no retail distribution or country of origin could be verified from the fetched pages, so credibility scores conservatively."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('JADÉ Complexions', 'https://www.jadecomplexions.com', 'Holistic-clinical skincare brand whose Affiliate Program is an exclusive, invite-only network tracked via ReferralCandy: invited affiliates earn 15% of net sale value on qualified referrals within a 30-day cookie, paid monthly via PayPal from a $50 threshold, under published terms effective May 30, 2025, with questions to hello@jadecomplexions.com.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'hello@jadecomplexions.com', null, 'https://www.jadecomplexions.com/pages/affiliate-program-terms-and-conditions', 'verified', now());
