  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'JADÉ Complexions Affiliate Program (invite-only, ReferralCandy)', null, 'https://www.jadecomplexions.com/pages/affiliate-program-terms-and-conditions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.jadecomplexions.com/pages/affiliate-program-terms-and-conditions', 'official_site', 'affiliate', 'JADÉ Complexions'' own published Affiliate Program Terms (effective 05/30/2025) state the program is ''an exclusive, invite-only network'' with ''No general application process'', that referrals are tracked via ReferralCandy with a 30-day cookie, and that ''Affiliates will earn a commission of 15% of the net sale value'' per Qualified Referral, paid monthly via PayPal from a $50 minimum. The terms publish no earnings-cap statement, so the cap is unknown. Contact for program questions: hello@jadecomplexions.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.jadecomplexions.com/pages/affiliate-program-terms-and-conditions', 'official_site', 'creator_saturation', 'The program is invite-only and deliberately small by design, but no absolute creator count is published, so creator saturation is recorded as unknown rather than low — invite-only wording alone is not a hard ~100-scale count.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 14, 11, 3, 3, '{"niche_fit": "Holistic-clinical skincare with an ingredient-and-results angle fits esthetician and skincare-education UGC.", "ugc_evidence": "A real affiliate network with published terms and disclosure rules, but it is positioned for invited partners rather than an open creator community.", "compensation": "A clean published 15% of net sale value in the brand''s own terms, with a 30-day cookie; cap unknown.", "contact_access": "Published program contact email (hello@jadecomplexions.com) in the brand''s own terms.", "opportunity_availability": "Invite-only with no general application process \u2014 the lowest availability in this round; a creator must be invited or pitch the contact email.", "credibility": "Small independent skincare brand with formal published program terms governed by California law; no retail distribution verified."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('utusori', 'https://www.utusori.com', 'Everyday clothing brand built around deliberate colour combinations, releasing two collections a year. Its year-round creator programme pays a 20% founding rate (15% standard after the founding group) on every eligible order through a creator''s code or link, with no posting quota, no exclusivity, and an explicit no-cap statement in its programme FAQ.', 'Canada', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.utusori.com/creators/.', 'https://www.utusori.com/creators/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'utusori Creator and Affiliate Program (founding group)', 'https://www.utusori.com/creators/', 'https://www.utusori.com/creators/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.utusori.com/creators/', 'official_program_page', 'affiliate_program', 'Official creator page: founding affiliates earn 20% on every eligible order for 12 months from activation, then the standard 15% with no end date; the page states ''There is no cap on what you can earn.'' Commission is on the eligible merchandise subtotal after discount; 30-day link window, code is the primary attribution; monthly payouts at a USD 25 / CAD 35 minimum.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.utusori.com/creators/', 'official_program_page', 'affiliate_program', 'Official FAQ on the same page answers ''Is there a cap on earnings?'' with ''No cap on valid commission from eligible orders.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.utusori.com/creators/', 'official_program_page', 'creator_program', 'Programme terms on the official page: no posting quota, no script, no exclusivity, creators keep ownership of their content; open to English-language creators anywhere whose audience is at least half US and Canada combined; follower count is not a screen. The page notes the programme activates only when the store''s checkout is live.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 19, 4, 7, 3, '{"compensation": "20% founding rate (15% standard after 12 months) with an explicit ''There is no cap on what you can earn'' statement and a matching FAQ answer.", "contact_access": "No email is published on the page; support runs through a form on the site.", "credibility": "Operated by Premium Framework Inc. (Ottawa, Canada) and Vodallo LLC (US) per its own FAQ, but a young, little-known label whose store checkout was not yet live at research time.", "niche_fit": "Colour-led everyday clothing maps directly onto styling, wardrobe-building and streetwear creator content.", "opportunity_availability": "Founding-group application is open, but the page states codes activate only when the store''s checkout opens, so availability is scored down.", "ugc_evidence": "Explicitly a creator programme (no quota, no script, content stays the creator''s), but no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('HatLaunch', 'https://www.hatlaunch.com', 'Custom embroidered hat brand selling made-to-order headwear for teams, brands and creators. Its own affiliate program pays a default 10% commission on every qualifying order through a custom short link, with a live dashboard, and states there is no cap on what affiliates can make.', null, 'published') returning id into bid;
