  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'HatLaunch Affiliate Program', 'https://www.hatlaunch.com/affiliates', 'https://www.hatlaunch.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hatlaunch.com/affiliates', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''Share your custom HatLaunch link. Earn cash on every qualifying order - no cap on what you can make.'' Default commission rate is 10% (adjustable per affiliate for large audiences), calculated on the subtotal after tax and shipping; commissions payable 30 days after the order date.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hatlaunch.com/affiliates', 'official_program_page', 'creator_program', 'Official page: program is ''Built for creators, sports teams, and anyone whose audience wears hats''; affiliates get a custom hatlaunch.com/yourcode link and a dashboard tracking clicks, orders and payouts; followers get 2 free hats on orders of 12 or more items. Applications are reviewed within a few business days.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 15, 4, 8, 3, '{"compensation": "Default 10% per order with an explicit ''no cap on what you can make'' statement; rate can be raised per affiliate at application.", "contact_access": "No email is published on the page; contact runs through the application form.", "credibility": "Operating custom-hat storefront with a defined affiliate operation, but a small brand with no published scale figures.", "niche_fit": "Custom hats are a wearable, easy-to-show fashion accessory for creator, team and merch content.", "opportunity_availability": "Open application on the official page, reviewed within a few business days.", "ugc_evidence": "Page is written for creators with dashboard tracking and shareable short links, but publishes no creator counts, so saturation stays unknown."}'::jsonb);
