  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.teamprokit.com/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''You earn 10% on every eligible order attributed to your link. The 30-day cookie... The more you share, the more you earn: there is no cap on commissions.'' FAQ repeats: ''You earn 10% on every eligible order through your link, with no cap on total earnings.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.teamprokit.com/pages/affiliate-program', 'official_program_page', 'creator_program', 'Official page: program is open to content creators (blogs, YouTube, TikTok, Instagram, podcasts), fan accounts and communities, and stores/resellers; no minimum following and no application fee; affiliates receive banners, product imagery and a dashboard; payouts monthly via PayPal once the balance reaches $50.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 15, 4, 9, 3, '{"compensation": "10% on every eligible order with an explicit ''no cap on commissions'' statement in both the terms section and the FAQ.", "contact_access": "No email address is printed in the fetched page text; the page says its support desk replies within 24 business hours.", "credibility": "Operating jersey storefront with published programme rules and payout terms, but a small, replica-focused brand.", "niche_fit": "Replica football jerseys map directly onto football fan, matchday and sports-fashion creator content.", "opportunity_availability": "Free and open to anyone with an audience; no minimum following, no fee.", "ugc_evidence": "Creators and fan communities are named as the target partners with ready-made creatives provided; no creator counts published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kalimi', 'https://kalimi.com', 'Travel eSIM provider selling data plans for travellers, remote workers and digital nomads. Its own affiliate program pays 20% on a referral''s first purchase and 10% lifetime on later top-ups, with a 180-day cookie, real-time dashboard, monthly payouts at a $50 threshold, and an FAQ stating there is no cap on earnings.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
