  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kalimi Affiliate Program', 'https://kalimi.com/affiliate', 'https://kalimi.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kalimi.com/affiliate', 'official_program_page', 'affiliate_program', 'Official affiliate page FAQ: ''You earn 20% on your referral''s first purchase and 10% on every purchase they make after that, for life. There''s no cap on how much you can earn.'' The lifetime tier requires at least 75 orders from new clients per month to unlock and keep, per the same page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kalimi.com/affiliate', 'official_program_page', 'affiliate_program', 'Official page: 180-day cookie (six times the stated 30-day standard), free to join, most partners approved within 24 hours, paid monthly in the first week of the month at a $50 minimum via bank transfer or PayPal; no minimum audience required.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kalimi.com/affiliate', 'official_program_page', 'creator_program', 'Official page names its target partners: travel bloggers, digital nomads, YouTubers, travel communities, newsletter writers, TikTok creators, comparison sites and tour operators; affiliates get banners, deep links, discount codes and a dedicated affiliate manager.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 18, 6, 9, 3, '{"compensation": "20% on first purchases plus 10% lifetime on top-ups, with an explicit ''There''s no cap on how much you can earn'' FAQ answer; the lifetime tier''s 75-orders-a-month condition is noted.", "contact_access": "A dedicated affiliate manager is promised on the official page, but the contact email was masked in the fetched copy, so no email is recorded.", "credibility": "Operating eSIM storefront with concrete published terms, but a smaller name than the major eSIM brands already in the directory.", "niche_fit": "eSIM data is a near-universal need in travel content, and the 180-day cookie suits slow-planning audiences.", "opportunity_availability": "Free signup with approval typically within 24 hours and no minimum audience.", "ugc_evidence": "Travel creators are named as core partners with ready-made creatives; no creator counts published, so saturation stays unknown."}'::jsonb);
