  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sg.thegravgear.com/pages/gravgear-affiliate-program', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''Refer to your followers, and earn 25% of all referred payments. There''s no limit to how much you can earn.'' and ''Get 25% commission on physical items and 30% for digital ones. No cap on earnings.'' Commission is paid within 5 days of the next month via PayPal.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sg.thegravgear.com/pages/gravgear-affiliate-program', 'official_program_page', 'creator_program', 'Official page eligibility table: content creators and influencers, athletes, fitness coaches, email newsletters, bloggers and writers, and media networks can all join; affiliates get a portal to create and track links plus a resource centre. Contact email published on the page: collabs@thegravgear.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 19, 11, 9, 3, '{"compensation": "25% on physical gear and 30% on digital products, with explicit ''No cap on earnings'' and ''no limit'' statements on the official page - one of the highest rates in this round.", "contact_access": "Published collaborations email (collabs@thegravgear.com) on the official affiliate page.", "credibility": "A real Singapore calisthenics-gear storefront, but a small regional brand, so credibility stays low.", "niche_fit": "Calisthenics and home-gym equipment demos and reviews are a natural fit for fitness creators.", "opportunity_availability": "Open application through the BixGrow affiliate portal linked from the official page.", "ugc_evidence": "Creators, athletes and coaches are the named eligible partners with a resource centre provided; no creator counts published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('AIBJJ', 'https://aibjj.com', 'AI-powered Brazilian Jiu-Jitsu training platform with an AI coach, technique library, training journal and game plan builder. Its affiliate program pays 30% recurring commission on every Pro subscription referred ($6/month per active referral at the $19.99 Pro price), with a 60-day cookie and an FAQ stating there is no earning cap.', null, 'published') returning id into bid;
