  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'AIBJJ Affiliate Program', 'https://aibjj.com/affiliates', 'https://aibjj.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aibjj.com/affiliates', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''Every time someone signs up for Pro, you earn 30% every single month they stay subscribed. No caps. No expiry.'' and the FAQ answers ''Is there an earning cap?'' with ''None. There''s no limit to how many referrals you can have or how much you can earn.'' Pro is $19.99/month, so each active referral pays $6/month; 60-day cookie; monthly payouts via PayPal or Stripe at a $50 minimum.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aibjj.com/affiliates', 'official_program_page', 'creator_program', 'Official page: target partners are BJJ academy owners, coaches and instructors, YouTubers and content creators, Instagram pages, podcast hosts and bloggers; creators who also sell instructionals on the platform earn 85% on their own instructional sales. Applications are reviewed within 2-3 business days and require a free AIBJJ account.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 19, 4, 8, 3, '{"compensation": "30% recurring for the life of each referred subscription, with an explicit ''no earning cap'' FAQ answer - a high, recurring rate, on a small $19.99 subscription base.", "contact_access": "No email is published on the page; applications run through the on-page form.", "credibility": "A niche, young AI training platform; transparent terms, but no proven scale is published.", "niche_fit": "A defined fit for BJJ and martial-arts creators, narrower than general fitness.", "opportunity_availability": "Open application with review in 2-3 business days; a free account is required first.", "ugc_evidence": "YouTubers, Instagram pages and podcasters are named target partners; no creator counts published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ISSA', 'https://www.issaonline.com', 'International Sports Sciences Association (ISSA), a long-running US fitness certification provider (personal training, nutrition coaching and specialisations). Its affiliate program is powered by Impact and pays commission on referred course purchases; the official page states there is no limit to how much affiliates can earn, but publishes no percentage rate.', 'United States', 'published') returning id into bid;
