  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ISSA Affiliate Program (Impact)', 'https://www.issaonline.com/pages/become-an-affiliate', 'https://www.issaonline.com/pages/become-an-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.issaonline.com/pages/become-an-affiliate', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''The ISSA Affiliate Program pays you for referring customers to issaonline.com... When customers make a purchase, you earn a commission for each valid transaction. There is no limit to how much you can earn. In 2022, our top partners earned over $100,000 in commission.'' No commission percentage is published anywhere on the page, so commission_rate is recorded as null rather than guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.issaonline.com/pages/become-an-affiliate', 'official_program_page', 'affiliate_program', 'Official page: ''The ISSA Affiliate Program is powered by Impact, the world''s leading partner automation platform'', with a dedicated affiliate team providing offers and setup support; partners place links on websites, blogs or social media pages.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 5, 9, 5, '{"compensation": "An explicit ''There is no limit to how much you can earn'' statement, but no percentage rate is published on the official page, so compensation scores low until the rate is confirmed inside Impact.", "contact_access": "No partnerships email is published on the page; contact runs through the Impact network and ISSA''s affiliate team.", "credibility": "Long-established US certification body running its program through Impact, a major network, with a published Phoenix, AZ address.", "niche_fit": "Fitness certification courses fit trainer and coach creators whose audiences want credentials, though it is education rather than a consumer product.", "opportunity_availability": "Open signup via the official page and the Impact network.", "ugc_evidence": "The page invites links on social media pages and names top partners, but publishes no creator counts, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Puppy Yoga Club', 'https://puppy-yogaclub.com', 'Puppy yoga experience brand running wellness classes with puppies across North America. Its affiliate program, tracked through UpPromote, pays 20% on every ticket and 15% lifetime on memberships, gives referrals a 10% discount, and states there is no limit to how much affiliates can earn.', null, 'published') returning id into bid;
