  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://puppy-yogaclub.com/pages/affiliate', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''Earn 20% on every ticket and 15% on memberships monthly, just by sharing your link. There''s no limit to how much you can earn.'' Memberships pay 15% lifetime; referrals receive a 10% discount; 30-day cookie; payments on the 7th of each month by bank transfer at a $50 minimum.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://puppy-yogaclub.com/pages/affiliate', 'official_program_page', 'creator_program', 'Official page: the program is aimed at YouTubers, content creators and content writers, and states ''Join +1500 affiliates'' - a four-figure affiliate count, so saturation is recorded as unknown, not low. Brand assets are offered on request via hello@puppy-yogaclub.com; paid ads and coupon sites are prohibited.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 16, 18, 11, 9, 3, '{"compensation": "20% on tickets and 15% lifetime on memberships, with an explicit ''There''s no limit to how much you can earn'' statement.", "contact_access": "Published email (hello@puppy-yogaclub.com) on the official affiliate page for brand assets and questions.", "credibility": "Operating experience brand with published payout terms, but a novelty, location-based offer rather than a product line.", "niche_fit": "Puppy yoga classes are highly visual, shareable fitness-experience content, though limited to the cities it operates in.", "opportunity_availability": "Apply-in-seconds signup through the UpPromote portal linked from the official page.", "ugc_evidence": "Creators are the named audience and the page itself reports 1,500+ affiliates, so the programme is active but not low-saturation."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Iron House', 'https://joinironhouse.com', 'Personal-trainer matching marketplace (IronHouse) that pairs clients with vetted trainers by personality, goals, coaching style and budget, with a free rematch guarantee. Its affiliate program generates an instant referral link and pays a flat $50 for every client signup, with no cap on earnings and monthly payouts via PayPal or Venmo.', null, 'published') returning id into bid;
