  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Iron House Affiliate Program', 'https://joinironhouse.com/affiliate.html', 'https://joinironhouse.com/affiliate.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://joinironhouse.com/affiliate.html', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''$50 per client signup'', ''No cap on earnings'', ''Monthly payouts'', ''Instant link generation''. ''Every person who clicks your link and signs up puts $50 in your pocket'' and the link never expires. The pay is a flat $50 bounty per signup, not a percentage, so commission_rate is recorded as null rather than as a percentage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://joinironhouse.com/affiliate.html', 'official_program_page', 'creator_program', 'Official page: signup takes about 30 seconds (name and email, optional Instagram handle) and the referral link is generated on the spot; payouts are processed monthly via PayPal or Venmo under the linked affiliate terms; matching is free for the client, with an average 48 hours to a matched trainer and a free rematch if the fit is wrong.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 14, 4, 10, 3, '{"compensation": "Flat $50 per client signup with an explicit ''No cap on earnings'' statement - a strong bounty, scored below percentage programs because it is a one-off signup payment, not a share of sales.", "contact_access": "A questions email is linked on the page but was masked in the fetched copy, so no email is recorded; signup is self-serve.", "credibility": "A young matching marketplace with clear terms and a rematch guarantee, but no published scale or track record.", "niche_fit": "Trainer matching speaks directly to fitness creators'' audiences, most of whom already want a trainer per the brand''s own pitch.", "opportunity_availability": "Instant link generation on a 30-second signup - the lowest-friction join in this round.", "ugc_evidence": "The pitch is written for fitness creators (bio links, video mentions, stories), but no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Just Because Jewelry', 'https://justbecausejewelry.com', 'Luxury lab-grown diamond jewellery brand built around self-gifting and everyday luxury. Its own affiliate program pays 10% commission on every referred sale with a 30-day cookie, a dedicated dashboard, monthly payouts, and states ''No cap on earnings - ever'', with approval typically within 48 hours.', null, 'published') returning id into bid;
