  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://justbecausejewelry.com/affiliate', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''10% Commission on every sale you refer'', ''30 Day cookie window on all online sales'', ''No cap on earnings - ever'', ''48h Approval turnaround after you apply''; and ''Earn 10% on every purchase made through your link - no cap, no limits.''', 'verified', now());
