  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 15, 4, 8, 3, '{"compensation": "10% on every sale with an explicit ''No cap on earnings - ever'' statement on the official page.", "contact_access": "No email is published on the page; applications run through the on-page form.", "credibility": "Operating lab-grown diamond storefront with defined affiliate terms, but a small, young luxury brand.", "niche_fit": "Lab-grown diamond jewellery fits gifting, self-gifting and everyday-luxury fashion content well.", "opportunity_availability": "Open application with approval typically within 48 hours.", "ugc_evidence": "The page is written for creators with dashboard tracking and early collection access, but publishes no creator counts, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Simply Sensitivity Checks', 'https://www.simplysensitivitychecks.com', 'At-home wellness testing brand selling hair-based sensitivity checks with practical diet and lifestyle guides, positioned explicitly as complementary wellness products rather than medical tests.', 'United States', 'published') returning id into bid;
