  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Simply Sensitivity Checks Affiliate Program (Impact)', 'https://www.simplysensitivitychecks.com/pages/affiliates', 'https://www.simplysensitivitychecks.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.simplysensitivitychecks.com/pages/affiliates', 'official_site', 'affiliate', 'Simply Sensitivity Checks'' official affiliate page publishes a 15% commission on every qualifying sale and states twice, verbatim: ''with no cap on what you can earn'' and in its FAQ ''There''s no cap, so the more people you introduce to us, the more you can earn.'' The program runs through Impact, tracks for 30 days, pays monthly once the balance reaches $10, and gives followers 10% off their first order. The cap is verified uncapped on the brand''s own page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.simplysensitivitychecks.com/pages/affiliates', 'official_site', 'contact', 'The same official page publishes partners@simplysensitivity.com for the partnerships team (replies within 2 business days), welcomes health, wellness, nutrition, food and lifestyle creators of any audience size, and states applications are reviewed by the brand''s team.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 18, 14, 8, 4, '{"niche_fit": "At-home sensitivity testing sits squarely in health, nutrition and food-intolerance creator content, and the brand names those exact creator types on its program page.", "ugc_evidence": "A structured Impact program with ready-to-use approved images, banners and product information for creator posts; no creator counts were published on fetched pages.", "compensation": "15% on every qualifying sale with a verified no-cap statement repeated on the official page.", "contact_access": "Published partners@simplysensitivity.com partnerships email with a stated 2-business-day reply time.", "opportunity_availability": "Free application through Impact, reviewed by the brand; no minimum sales target and no large following required.", "credibility": "The brand is careful to position its tests as wellness products, not medical tests, with explicit promotion guidelines - responsible, but a smaller and younger brand, so held at 4."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Maker Wine', 'https://www.makerwine.com', 'Premium canned wine brand partnering with small, independent winemakers to sell single-serve, minimal-intervention wines fermented dry with no residual sugar, through its own online store.', 'United States', 'published') returning id into bid;
