  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Maker Wine Cannoisseur Affiliate Crew', 'https://www.makerwine.com/affiliates/', 'https://www.makerwine.com/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.makerwine.com/affiliates/', 'official_site', 'affiliate', 'Maker Wine''s official Cannoisseur affiliate page publishes a 15% commission on all sales and states, verbatim: ''Any purchases made using your personal link will earn you 15% of the purchase price. There''s no cap on what you can earn.'' Affiliates get a personal link, an affiliate portal with metrics, tasting notes, professional images and guided tastings, early access to new releases, and followers get 15% off. The cap is verified uncapped on the brand''s own page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.makerwine.com/affiliates/', 'official_site', 'general', 'The same official page names a dedicated affiliate marketing manager (Brielle) as the point of contact for the Crew and shows a 4.8 rating from 1,276 reviews; no program email was published in readable form on the fetched page, so no contact is recorded.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 17, 6, 9, 5, '{"niche_fit": "Single-serve premium canned wine from small producers is highly shareable food-and-drink content - tastings, hosting, picnics and gift guides.", "ugc_evidence": "A named creator community (the Cannoisseur Crew) with an affiliate portal, tasting notes, professional images and guided tastings supplied for content; no creator counts were published on fetched pages.", "compensation": "15% on all sales with a verified ''no cap on what you can earn'' statement on the official page.", "contact_access": "A named affiliate manager is the point of contact via a meeting link on the page, but no program email was published, so held at 6.", "opportunity_availability": "Open sign-up form on the brand''s own affiliate page with a personalised shareable link.", "credibility": "Established DTC wine brand showing a 4.8 rating across 1,276 reviews on its own affiliate page, with a named affiliate manager."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Thorne', 'https://www.thorne.com', 'Practitioner-grade supplement brand selling science-backed vitamins, supplements and performance products through its own store, with a separate professional channel for certified health practitioners.', 'United States', 'published') returning id into bid;
