  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.thorne.com/ambassador', 'official_site', 'affiliate', 'Thorne''s official Ambassador page states ambassadors earn commission on every new customer order placed through their personal link, with free product opportunities, early access to launches and a follower discount. The page does NOT publish a commission percentage - its linked FAQ states the structure is tiered and full details are given once accepted - so commission_rate is recorded as null. No cap statement appears on any fetched official page, so the cap is recorded as unknown, never guessed.', 'verified', now());
