  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 14, 10, 6, 8, 5, '{"niche_fit": "A vast supplements, herbs and wellness grocery catalogue gives health creators an unusually wide, linkable product surface.", "ugc_evidence": "A long-running network affiliate program explicitly open to content sites and social promotion under its terms; no creator counts were published on fetched pages, and a retailer program is less UGC-specific than a brand ambassador program.", "compensation": "5% default is low for the niche, though qualified content sites may earn higher rates at iHerb''s discretion.", "contact_access": "No program email was published in the fetched terms; contact runs through the affiliate platform accounts.", "opportunity_availability": "Application via any of its listed affiliate platforms, subject to iHerb approval of sites and social profiles.", "credibility": "One of the largest global wellness retailers, with detailed, current (October 2026) published affiliate terms."}'::jsonb);
