  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://puralityhealth.com/affiliate/', 'official_site', 'affiliate', 'Purality Health''s official affiliate page answers ''How much can I earn?'' with, verbatim: ''The sky is the limit! There is no maximum cap.'' The program runs through ClickBank or HasOffers|Tune (with its magnesium product also on Digistore24), has no minimum payout threshold, pays HasOffers partners twice monthly and ClickBank partners bi-weekly, and requires a W9/W8BEN. The page promises ''competitive commission rates'' but publishes NO percentage anywhere on the fetched page, so commission_rate is recorded as null. The cap is verified uncapped on the brand''s own FAQ.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 14, 6, 7, 4, '{"niche_fit": "Liposomal supplements with an absorption-technology story fit supplement-review and wellness creator content well.", "ugc_evidence": "A partner program with a no-login resource portal of tested email swipes and banners and partner testimonials; oriented more to affiliate marketers than UGC creators, and no creator counts were published.", "compensation": "Earnings cap is verified uncapped (''no maximum cap'') in the official FAQ, but the commission percentage itself is not published, so scored conservatively.", "contact_access": "No published program email was found; applications are personally reviewed through the form on the affiliate page.", "opportunity_availability": "Registration form on the official page with personal review of each application.", "credibility": "Claims over 1,000,000 bottles sold and a 180-day money-back guarantee on its own page; a direct-response style brand, so held at 4."}'::jsonb);
