  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://atomebakery.com/pages/affiliates', 'official_site', 'affiliate', 'Atome''s official affiliate page publishes 4% of every new customer''s first order, tracked and paid by Impact, with a 30-day referral window, and states, verbatim: ''No cap on what you can earn'' and in its FAQ ''There is no cap on your earnings.'' Commission applies ONLY to a referred customer''s first-ever order - repeat orders earn nothing - and payouts are automatic on the 1st or 15th once the balance reaches $10. The cap is verified uncapped on the brand''s own page, with the first-order-only basis recorded so it cannot be misread.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 8, 6, 8, 4, '{"niche_fit": "Ready-to-bake sourdough and pastries are highly visual, repeatable food content - bakes, brunches and hosting - with a clear Canadian creator angle.", "ugc_evidence": "The program page explicitly recruits food, baking, lifestyle and family creators and suggests reels, recipes and gift guides; no creator counts were published on fetched pages.", "compensation": "Only 4% and only on a new customer''s first order, though the earnings cap is verified uncapped - the weakest rate structure in this batch.", "contact_access": "No program email was published; applications and contact run through Impact.", "opportunity_availability": "Application on Impact with brand review of every application; an established online presence is required but need not be a website.", "credibility": "Named founders, a founded-2022 Vancouver bakery with detailed delivery and program terms on its own site."}'::jsonb);
