  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 9, 6, 7, 4, '{"niche_fit": "Plant-based ready-to-eat meals and smoothies are a staple of wellness, busy-routine and plant-based creator content.", "ugc_evidence": "A network affiliate program aimed at health and organic-living publishers, plus a separate ambassador community described in published reviews; no creator counts were published on fetched pages.", "compensation": "A flat per-subscription bounty exists but conflicts across sources ($24 vs $40) with no percentage published, so scored low with rate null until confirmed in the network.", "contact_access": "No program email was published on fetched pages; contact runs through the affiliate network.", "opportunity_availability": "Network application with a few days'' stated approval time per the directory listing.", "credibility": "Well-known US plant-based meal delivery brand; held at 4 because this entry rests on directory sources rather than a fetched official program page."}'::jsonb);
